// A burst of acks far above the bandwidth estimate raises the degree of ack aggregation. The
// window term it adds is capped at 100 ms of packets at the current bandwidth (400 packets at 4
// packets/ms), and the stored value rotates to the other window after five rounds.
// Upstream run: libudx ae8bff7 src/udx_bbr.c through the scratch C harness.
func TestBBRAckAggregationCapLikeUpstream(t *testing.T) {
	defer failOnPanic(t)
	f := &bbrFlow{cwnd: 10, srtt: 50}
	f.initBBR(1000, 50)
	checkBBR(t, f, "init", bbrWant{state: bbrStartup, cycle: 0, cwnd: 10, pacing: 658, bw: 0.0, minRTT: 50, minStamp: 1000, fullBW: false})
	bbrAck(f, 1050, 50, 40, rateSample{intervalMS: 50, delivered: 50, ackedSacked: 50, rttMS: 50})
	checkBBR(t, f, "ack 1050", bbrWant{state: bbrStartup, cycle: 0, cwnd: 60, pacing: 3290, bw: 1.0, minRTT: 50, minStamp: 1000, fullBW: false})
	wantEq(t, "ack 1050", "rttcount", f.bbr.rttCount, 1)
	wantEq(t, "ack 1050", "delivered", f.rate.delivered, 50)
	wantEq(t, "ack 1050", "gainp", f.bbr.pacingGain, float32(2.88539004))
	wantEq(t, "ack 1050", "gainc", f.bbr.cwndGain, float32(2.88539004))
	bbrAck(f, 1100, 150, 60, rateSample{intervalMS: 50, delivered: 100, priorDelivered: 50, ackedSacked: 100, rttMS: 50})
	checkBBR(t, f, "ack 1100", bbrWant{state: bbrStartup, cycle: 0, cwnd: 160, pacing: 6581, bw: 2.0, minRTT: 50, minStamp: 1000, fullBW: false})
	bbrAck(f, 1150, 300, 80, rateSample{intervalMS: 50, delivered: 150, priorDelivered: 150, ackedSacked: 150, rttMS: 50})
	checkBBR(t, f, "ack 1150", bbrWant{state: bbrStartup, cycle: 0, cwnd: 310, pacing: 9872, bw: 3.0, minRTT: 50, minStamp: 1000, fullBW: false})
	bbrAck(f, 1200, 500, 100, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 300, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1200", bbrWant{state: bbrStartup, cycle: 0, cwnd: 510, pacing: 13162, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: false})
	bbrAck(f, 1250, 700, 120, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 500, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1250", bbrWant{state: bbrStartup, cycle: 0, cwnd: 710, pacing: 13162, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: false})
	bbrAck(f, 1300, 900, 140, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 700, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1300", bbrWant{state: bbrStartup, cycle: 0, cwnd: 710, pacing: 13162, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: false})
	bbrAck(f, 1350, 1100, 400, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 900, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1350", bbrWant{state: bbrDrain, cycle: 0, cwnd: 777, pacing: 1581, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1350", "gainp", f.bbr.pacingGain, float32(0.346573591))
	wantEq(t, "ack 1350", "gainc", f.bbr.cwndGain, float32(2.88539004))
	bbrAck(f, 1400, 1300, 150, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 1100, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1400", bbrWant{state: bbrProbeBW, cycle: 4, cwnd: 600, pacing: 4561, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1400", "gainp", f.bbr.pacingGain, float32(1))
	wantEq(t, "ack 1400", "gainc", f.bbr.cwndGain, float32(2))
	bbrAck(f, 1460, 1900, 150, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 1300, ackedSacked: 600, rttMS: 50})
	checkBBR(t, f, "ack 1460", bbrWant{state: bbrProbeBW, cycle: 5, cwnd: 800, pacing: 4561, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1460", "ea0", f.bbr.extraAcked[0], 200)
	wantEq(t, "ack 1460", "ea1", f.bbr.extraAcked[1], 600)
	wantEq(t, "ack 1460", "epochacked", f.bbr.ackEpochAcked, 600)
	bbrAck(f, 1520, 2100, 150, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 1900, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1520", bbrWant{state: bbrProbeBW, cycle: 6, cwnd: 800, pacing: 4561, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1520", "ea0", f.bbr.extraAcked[0], 560)
	wantEq(t, "ack 1520", "ea1", f.bbr.extraAcked[1], 600)
	wantEq(t, "ack 1520", "epochacked", f.bbr.ackEpochAcked, 800)
	bbrAck(f, 1580, 2300, 150, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 2100, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1580", bbrWant{state: bbrProbeBW, cycle: 7, cwnd: 800, pacing: 4561, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1580", "ea0", f.bbr.extraAcked[0], 560)
	wantEq(t, "ack 1580", "ea1", f.bbr.extraAcked[1], 600)
	wantEq(t, "ack 1580", "epochacked", f.bbr.ackEpochAcked, 1000)
	bbrAck(f, 1640, 2500, 150, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 2300, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1640", bbrWant{state: bbrProbeBW, cycle: 0, cwnd: 800, pacing: 5702, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1640", "ea0", f.bbr.extraAcked[0], 560)
	wantEq(t, "ack 1640", "ea1", f.bbr.extraAcked[1], 600)
	wantEq(t, "ack 1640", "epochacked", f.bbr.ackEpochAcked, 1200)
	bbrAck(f, 1700, 2700, 150, rateSample{intervalMS: 50, delivered: 200, priorDelivered: 2500, ackedSacked: 200, rttMS: 50})
	checkBBR(t, f, "ack 1700", bbrWant{state: bbrProbeBW, cycle: 0, cwnd: 800, pacing: 5702, bw: 4.0, minRTT: 50, minStamp: 1000, fullBW: true})
	wantEq(t, "ack 1700", "ea0", f.bbr.extraAcked[0], 560)
	wantEq(t, "ack 1700", "ea1", f.bbr.extraAcked[1], 600)
	wantEq(t, "ack 1700", "epochacked", f.bbr.ackEpochAcked, 1400)
	wantEq(t, "ack 1700", "epochstart", f.bbr.ackEpochStart, 1460)
}

