// A flow with no RTT sample yet: the pacing rate starts from cwnd over 1 ms, has_seen_rtt stays
// false, and the min RTT is the filter's reset value (~0) until a sample arrives. Upstream run:
// bbr_init with srtt 0 and udx_rtt_min ~0.
func TestBBRInitWithoutRTTSampleLikeUpstream(t *testing.T) {
	defer failOnPanic(t)
	f := &bbrFlow{cwnd: 10}
	f.initBBR(1000, ^uint32(0))
	checkBBR(t, f, "init", bbrWant{state: bbrStartup, cycle: 0, cwnd: 10, pacing: 32907, bw: 0, minRTT: ^uint32(0), minStamp: 1000, fullBW: false})
	wantEq(t, "init", "hasrtt", f.bbr.hasSeenRTT, false)
	wantEq(t, "init", "prevca", f.bbr.prevCAState, caOpen)
	wantEq(t, "init", "epochstart", f.bbr.ackEpochStart, uint64(1000))
}

// The helpers that udx_bbr.c computes with: the pacing rate (bw x mss x gain x 0.99, truncated,
// at least 1), the BDP (bw x min RTT x gain, at least 1 packet, 10 before any RTT sample), and
// the two time differences. Upstream values come from the C helpers themselves.
func TestBBRHelpersLikeUpstream(t *testing.T) {
	defer failOnPanic(t)
	f := &bbrFlow{}
	wantEq(t, "helpers", "pacing 0.1 x high gain", f.bwToPacingRate(0.1, 2.88539), uint64(329))
	wantEq(t, "helpers", "pacing 10 x 1.0", f.bwToPacingRate(10, 1.0), uint64(11404))
	wantEq(t, "helpers", "pacing 0 is at least 1", f.bwToPacingRate(0, 2.0), uint64(1))
	wantEq(t, "helpers", "pacing 0.001 x 1.0 is at least 1", f.bwToPacingRate(0.001, 1.0), uint64(1))

	f.bbr.minRTTms = 100
	wantEq(t, "helpers", "bdp 0.1 x 100", f.bdp(0.1, 1.0), uint32(10))
	wantEq(t, "helpers", "bdp 0.05 x 100", f.bdp(0.05, 1.0), uint32(5))
	wantEq(t, "helpers", "bdp is at least 1", f.bdp(0.001, 1.0), uint32(1))
	f.bbr.minRTTms = ^uint32(0)
	wantEq(t, "helpers", "bdp before any RTT sample is 10", f.bdp(0.5, 2.0), uint32(10))

	wantEq(t, "helpers", "time_delta_ms forward", timeDeltaMS(1120, 1000), uint32(120))
	// time_delta_ms converts a negative difference to uint32 without clamping, so it wraps.
	wantEq(t, "helpers", "time_delta_ms backward wraps", timeDeltaMS(1000, 1120), uint32(4294967176))
	wantEq(t, "helpers", "time_diff backward is signed", timeDiff(1000, 1120), int64(-120))
	wantEq(t, "helpers", "time_diff forward", timeDiff(1120, 1000), int64(120))
}
